begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','withdraw_flight_request',array['uuid','uuid'],'Requester withdrawal RPC exists');
insert into auth.users(id,email) select ('19500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'withdraw-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.memberships(user_id,role) select ('19500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,4) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('19500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Withdrawal pilot','KPAO','licensed' from generate_series(2,3) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('19510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19500000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',1,case when n=3 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,5) n;
insert into public.flight_recipients(flight_id,user_id) values('19510000-0000-4000-8000-000000000003','19500000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id,introductory_note) select ('19520000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('19510000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19500000-0000-4000-8000-000000000002','Retained introduction' from generate_series(1,5) n;
insert into public.flight_requests(id,flight_id,requester_id) values('19520000-0000-4000-8000-000000000099','19510000-0000-4000-8000-000000000002','19500000-0000-4000-8000-000000000003');
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('19500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.withdraw(f integer default 1,r integer default 1) returns jsonb language sql as $$select public.withdraw_flight_request(('19510000-0000-4000-8000-'||lpad(f::text,12,'0'))::uuid,('19520000-0000-4000-8000-'||lpad(r::text,12,'0'))::uuid);$$;
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.withdraw_flight_request(uuid,uuid)'::regprocedure),'Withdrawal definer has fixed empty search path');
select ok(has_function_privilege('authenticated','public.withdraw_flight_request(uuid,uuid)','EXECUTE'),'Authenticated execute granted');
select ok(not has_function_privilege('anon','public.withdraw_flight_request(uuid,uuid)','EXECUTE'),'Anonymous execute revoked');
select ok(not has_function_privilege('service_role','public.withdraw_flight_request(uuid,uuid)','EXECUTE'),'Service-role execute revoked');
set local role anon;
select throws_ok($$select pg_temp.withdraw()$$,'42501',null,'Anonymous cannot withdraw');
reset role;
set local role service_role;
select throws_ok($$select pg_temp.withdraw()$$,'42501',null,'Service role cannot execute');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.withdraw()$$,'42501',null,'Missing identity denied');
select pg_temp.actor(5);
select throws_ok($$select pg_temp.withdraw()$$,'42501',null,'Missing membership cannot spoof access');
select pg_temp.actor(1);
select is(pg_temp.withdraw(),'{"code":"request_unavailable"}'::jsonb,'Owner cannot withdraw another pilot request');
select pg_temp.actor(4);
select is(pg_temp.withdraw(),'{"code":"request_unavailable"}'::jsonb,'Unrelated admin has no bypass');
select pg_temp.actor(3);
select is(pg_temp.withdraw(),'{"code":"request_unavailable"}'::jsonb,'Another requester cannot withdraw');
select pg_temp.actor(2);
select is(pg_temp.withdraw(1,2),'{"code":"request_unavailable"}'::jsonb,'Wrong flight binding unavailable');
select is(pg_temp.withdraw(99),'{"code":"request_unavailable"}'::jsonb,'Missing flight shares unavailable result');
select is(pg_temp.withdraw(1,98),'{"code":"request_unavailable"}'::jsonb,'Missing request shares unavailable result');
select throws_ok($$select public.withdraw_flight_request(null,'19520000-0000-4000-8000-000000000001')$$,'22023',null,'Null flight rejected');
select throws_ok($$select public.withdraw_flight_request('19510000-0000-4000-8000-000000000001',null)$$,'22023',null,'Null request rejected');
select throws_ok($$update public.flight_requests set status='withdrawn'$$,'42501',null,'Direct requester updates remain closed');
select is(pg_temp.withdraw(),'{"code":"withdrawn","requestId":"19520000-0000-4000-8000-000000000001","status":"withdrawn"}'::jsonb,'Requester withdraws pending with minimal confirmation');
reset role;
create temporary table withdrawn_snapshot as select to_jsonb(r) as row from public.flight_requests r where id='19520000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.withdraw()->>'code','already_withdrawn','Repeated withdrawal confirms without update');
reset role;
select is((select to_jsonb(r) from public.flight_requests r where id='19520000-0000-4000-8000-000000000001'),(select row from withdrawn_snapshot),'Retry preserves complete record');
update public.flight_requests set status='accepted' where id='19520000-0000-4000-8000-000000000002';
create temporary table accepted_identity as select id,flight_id,requester_id,created_at,introductory_note from public.flight_requests where id='19520000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.withdraw(2,2)->>'code','withdrawn','Accepted request may be withdrawn');
reset role;
select is((select count(*)::integer from public.flight_requests where flight_id='19510000-0000-4000-8000-000000000002' and status='accepted'),0,'Accepted withdrawal releases derived capacity');
select results_eq($$select id,flight_id,requester_id,created_at,introductory_note from public.flight_requests where id='19520000-0000-4000-8000-000000000002'$$,$$select * from accepted_identity$$,'Withdrawal retains identity, original creation and note');
set local role authenticated;
select is(public.submit_flight_interest('19510000-0000-4000-8000-000000000002','Fresh introduction'),'{"code":"submitted","requestId":"19520000-0000-4000-8000-000000000002","status":"pending"}'::jsonb,'Accepted withdrawal resubmits same record as pending');
reset role;
select is((select introductory_note from public.flight_requests where id='19520000-0000-4000-8000-000000000002'),'Fresh introduction','Resubmission replaces note');
select is((select created_at from public.flight_requests where id='19520000-0000-4000-8000-000000000002'),(select created_at from accepted_identity),'Resubmission preserves original creation time');
update public.flight_requests set status='accepted' where id='19520000-0000-4000-8000-000000000099';
set local role authenticated;
select is(pg_temp.withdraw(2,2)->>'code','withdrawn','Pending withdrawal permitted when flight full');
select is(public.submit_flight_interest('19510000-0000-4000-8000-000000000002')->>'code','flight_unavailable','Full capacity blocks resubmission');
reset role;
update public.flight_requests set status='declined' where id='19520000-0000-4000-8000-000000000004';
update public.flight_requests set status='cancelled' where id='19520000-0000-4000-8000-000000000005';
set local role authenticated;
select is(pg_temp.withdraw(4,4),'{"code":"request_conflict"}'::jsonb,'Declined remains terminal');
select is(pg_temp.withdraw(5,5),'{"code":"request_conflict"}'::jsonb,'Cancelled remains terminal');
reset role;
update public.flights set departure_at=clock_timestamp()+interval '5 seconds' where id='19510000-0000-4000-8000-000000000003';
update public.flight_requests set status='accepted' where id='19520000-0000-4000-8000-000000000003';
select pg_sleep(greatest(0,extract(epoch from departure_at-clock_timestamp()))+0.05) from public.flights where id='19510000-0000-4000-8000-000000000003';
delete from public.flight_recipients where flight_id='19510000-0000-4000-8000-000000000003';
update public.flights set status='completed' where id='19510000-0000-4000-8000-000000000003';
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned fixture' where user_id='19500000-0000-4000-8000-000000000001';
delete from public.profiles where user_id='19500000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.withdraw(3,3)->>'code','withdrawn','Withdrawal closes history despite unavailable flight/owner/profile/selection');
select throws_ok($$select public.submit_flight_interest('19510000-0000-4000-8000-000000000003')$$,'42501',null,'Resubmission still requires current profile');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned fixture' where user_id='19500000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select pg_temp.withdraw()$$,'42501',null,'Disabled requester cannot even confirm withdrawal');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id in ('19500000-0000-4000-8000-000000000001','19500000-0000-4000-8000-000000000002');
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('19500000-0000-4000-8000-000000000002','Withdrawal pilot','KPAO','licensed');
update public.flight_requests set status='pending' where id='19520000-0000-4000-8000-000000000001';
update public.flight_requests set status='accepted' where id='19520000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.get_or_create_flight_conversation('19520000-0000-4000-8000-000000000001')$$,'Accepted pair can create integrated conversation');
select is(pg_temp.withdraw()->>'code','withdrawn','Integrated conversation no longer fences accepted withdrawal');
select ok((select closed_at is not null from public.conversations where flight_request_id='19520000-0000-4000-8000-000000000001'),'Accepted withdrawal closes conversation while retaining history');
reset role;
select * from finish();
rollback;
